out.push("\n\n### 4.4 JavaScript 实现\n\n```javascript\nconst root = document.querySelector('#address-actions');\nconst trigger = root.querySelector('#actions-button');\nconst menu = root.querySelector('[role=\"menu\"]');\n\nconst items = [\n  ...menu.querySelectorAll('[role=\"menuitem\"]')\n];\n\nlet activeIndex = 0;\n\nfunction focusItem(index) {\n  activeIndex =\n    (index + items.length) % items.length;\n\n  items[activeIndex].focus();\n}\n\nfunction openMenu(index = 0) {\n  menu.hidden = false;\n\n  trigger.setAttribute('aria-expanded', 'true');\n\n  focusItem(index);\n}\n\nfunction closeMenu(restoreFocus = false) {\n  trigger.setAttribute('aria-expanded', 'false');\n\n  if (restoreFocus) {\n    trigger.focus();\n  }\n\n  menu.hidden = true;\n}\n\ntrigger.addEventListener('click', () => {\n  menu.hidden\n    ? openMenu()\n    : closeMenu(true);\n});\n\ntrigger.addEventListener('keydown', event => {\n  if (event.key === 'ArrowDown') {\n    event.preventDefault();\n    openMenu(0);\n  }\n\n  if (event.key === 'ArrowUp') {\n    event.preventDefault();\n    openMenu(items.length - 1);\n  }\n});\n\nmenu.addEventListener('keydown', event => {\n  switch (event.key) {\n    case 'ArrowDown':\n      event.preventDefault();\n      focusItem(activeIndex + 1);\n      break;\n\n    case 'ArrowUp':\n      event.preventDefault();\n      focusItem(activeIndex - 1);\n      break;\n\n    case 'Home':\n      event.preventDefault();\n      focusItem(0);\n      break;\n\n    case 'End':\n      event.preventDefault();\n      focusItem(items.length - 1);\n      break;\n\n    case 'Escape':\n      event.preventDefault();\n      event.stopPropagation();\n      closeMenu(true);\n      break;\n\n    case 'Tab':\n      // 返回菜单入口，再让浏览器继续顺序导航\n      closeMenu(true);\n      break;\n  }\n});\n\nmenu.addEventListener('focusin', event => {\n  const index = items.indexOf(event.target);\n\n  if (index !== -1) {\n    activeIndex = index;\n  }\n});\n\nitems.forEach(item => {\n  item.addEventListener('click', () => {\n    closeMenu(true);\n\n    // 业务层函数\n    executeAction(item.dataset.action);\n  });\n});\n\nroot.addEventListener('focusout', event => {\n  if (\n    event.relatedTarget &&\n    !root.contains(event.relatedTarget)\n  ) {\n    closeMenu();\n  }\n});\n\ndocument.addEventListener('click', event => {\n  if (!root.contains(event.target)) {\n    closeMenu(menu.contains(document.activeElement));\n  }\n});\n```\n\n这里使用真实 DOM 焦点在 menuitem 之间移动，但所有菜单项都保持 `tabindex=\"-1\"`。\n\n因为菜单打开时，由 JavaScript 主动设置内部焦点；菜单项不需要成为页面的常规 Tab 入口。\n\n原生 button 已经支持 Enter 和 Space，因此不需要重复实现命令激活。\n\n上述示例针对单层命令菜单；多级子菜单、动态菜单项以及不同浏览器中的 Tab 离开行为还需要进一步测试。\n\n### 4.5 Typeahead 字符快速定位\n\n例如用户打开一个国家选择菜单，然后按下 `c`，焦点移动到 Canada。\n\n对于 Menu 和 Listbox，可以在相应模式中提供这种快捷导航。\n\n```javascript\nfunction findByCharacter(character) {\n  const key = character.toLocaleLowerCase();\n\n  for (let offset = 1; offset <= items.length; offset++) {\n    const index =\n      (activeIndex + offset) % items.length;\n\n    const label = items[index].textContent\n      .trim()\n      .toLocaleLowerCase();\n\n    if (label.startsWith(key)) {\n      return index;\n    }\n  }\n\n  return -1;\n}\n\nmenu.addEventListener('keydown', event => {\n  if (\n    event.isComposing ||\n    event.ctrlKey ||\n    event.altKey ||\n    event.metaKey ||\n    event.key.length !== 1 ||\n    event.key === ' '\n  ) {\n    return;\n  }\n\n  const index = findByCharacter(event.key);\n\n  if (index >= 0) {\n    event.preventDefault();\n    focusItem(index);\n  }\n});\n```\n\n这是单字符匹配实现。更完整的 Typeahead 可以增加字符缓冲区、输入超时、多语言字符串匹配和重复字符循环。\n\n特别注意，不要将这种字符拦截逻辑直接应用到可编辑 Combobox 的 input 上，否则会影响用户正常输入文字。\n\n---\n\n## 5. Listbox：选择值，而不是执行命令\n\nMenu 和 Listbox 的视觉效果可能完全相同，但是它们承担不同职责。\n\n");
