out.push("\n\n### 8.2 HTML 与 Liquid 实现\n\n```liquid\n<form\n  id=\"ProductSearch\"\n  action=\"{{ routes.search_url }}\"\n  method=\"get\"\n  role=\"search\"\n  class=\"product-search\"\n>\n  <label for=\"SearchInput\">\n    Search products\n  </label>\n\n  <input\n    id=\"SearchInput\"\n    type=\"search\"\n    name=\"q\"\n    role=\"combobox\"\n    aria-expanded=\"false\"\n    aria-controls=\"SearchResults\"\n    aria-autocomplete=\"list\"\n    autocomplete=\"off\"\n  >\n\n  <button type=\"submit\">\n    Search\n  </button>\n\n  <ul\n    id=\"SearchResults\"\n    role=\"listbox\"\n    aria-label=\"Search suggestions\"\n    hidden\n  ></ul>\n\n  <p\n    id=\"SearchStatus\"\n    role=\"status\"\n    aria-atomic=\"true\"\n    class=\"visually-hidden\"\n  ></p>\n\n</form>\n```\n\n这里保留了原生搜索表单。\n\n即使 JavaScript 加载失败，用户也可以输入关键词并正常提交搜索请求。这就是 Progressive Enhancement（渐进增强）。\n\n示例假设页面只有一个搜索实例；如果 Header、Search Modal 和搜索结果页同时存在搜索组件，需要为每个实例生成唯一 ID。\n\n### 8.3 CSS 样式\n\n```css\n.product-search {\n  position: relative;\n}\n\n#SearchResults {\n  position: absolute;\n  inset-inline: 0;\n  top: 100%;\n\n  z-index: 20;\n  max-height: 320px;\n  overflow-y: auto;\n\n  margin: 0;\n  padding: 8px;\n\n  list-style: none;\n  background: white;\n  color: #222;\n  border: 1px solid #777;\n}\n\n#SearchResults[hidden] {\n  display: none;\n}\n\n#SearchResults [role=\"option\"] {\n  padding: 12px;\n  cursor: pointer;\n}\n\n#SearchResults [aria-selected=\"true\"] {\n  background: #eef3fa;\n  outline: 2px solid #005fcc;\n  outline-offset: -2px;\n}\n```\n\n为什么这里不直接使用 `:focus` 高亮建议项？\n\n因为 DOM 焦点始终在 input 上。\n\n建议项的视觉高亮需要通过 `aria-selected` 或其他活动状态 class 来实现。\n\n### 8.4 JavaScript：状态管理\n\n```javascript\nconst form = document.querySelector('#ProductSearch');\nconst input = form.querySelector('#SearchInput');\nconst list = form.querySelector('#SearchResults');\nconst status = form.querySelector('#SearchStatus');\n\nlet results = [];\nlet activeIndex = -1;\n\nlet debounceTimer;\nlet controller;\nlet requestVersion = 0;\n\nfunction setActive(index) {\n  activeIndex = index;\n\n  const options = [...list.children];\n\n  options.forEach((option, i) => {\n    option.setAttribute(\n      'aria-selected',\n      String(i === index)\n    );\n  });\n\n  const active = options[index];\n\n  if (!active) {\n    input.removeAttribute('aria-activedescendant');\n    return;\n  }\n\n  input.setAttribute(\n    'aria-activedescendant',\n    active.id\n  );\n\n  active.scrollIntoView({\n    block: 'nearest',\n    behavior: 'instant'\n  });\n}\n\nfunction openResults() {\n  if (!results.length) return;\n\n  list.hidden = false;\n\n  input.setAttribute('aria-expanded', 'true');\n}\n\nfunction hideResults() {\n  setActive(-1);\n\n  list.hidden = true;\n\n  input.setAttribute('aria-expanded', 'false');\n}\n```\n\n这里将展开状态、活动项、选中状态及视觉样式统一管理。\n\n### 8.5 JavaScript：渲染建议列表\n\n```javascript\nfunction renderResults(items) {\n  // 删除旧 DOM 前清理活动项引用\n  setActive(-1);\n\n  results = items;\n\n  const fragment = document.createDocumentFragment();\n\n  items.forEach((item, index) => {\n    const option = document.createElement('li');\n\n    option.id = `${list.id}-option-${index}`;\n\n    option.setAttribute('role', 'option');\n    option.setAttribute('aria-selected', 'false');\n\n    option.dataset.index = index;\n\n    option.textContent = item.title;\n\n    fragment.appendChild(option);\n  });\n\n  list.replaceChildren(fragment);\n\n  if (items.length) {\n    openResults();\n  } else {\n    hideResults();\n  }\n\n  status.textContent =\n    `${items.length} suggestions available.`;\n}\n```\n\n注意，这里没有将整个 Listbox 设置为 Live Region。\n\n根据第 14 课的知识，Live Region 只负责通知搜索结果数量，`aria-activedescendant` 则负责活动项变化。\n\n### 8.6 JavaScript：接入 Shopify Predictive Search API\n\nShopify 提供两种主要的 Predictive Search 响应形式：\n\n| API | 响应内容 |\n|---|---|\n| `/search/suggest.json` | JSON 数据 |\n| `/search/suggest` + `section_id` | 服务端渲染的 Section HTML |\n\nDawn 主要采用第二种方式。本示例采用 JSON 方式，以便更清楚地展示组件内部的状态管理。");
