out.push("\n\n```javascript\nfunction cancelPendingSearch() {\n  requestVersion++;\n\n  clearTimeout(debounceTimer);\n\n  controller?.abort();\n\n  list.setAttribute('aria-busy', 'false');\n}\n\nfunction dismissResults() {\n  cancelPendingSearch();\n  hideResults();\n\n  status.textContent = '';\n}\n\nasync function fetchSuggestions(query, version) {\n  const request = new AbortController();\n\n  controller = request;\n\n  const params = new URLSearchParams({\n    q: query,\n    'resources[type]': 'product',\n    'resources[limit]': '6'\n  });\n\n  const url =\n    window.Shopify.routes.root +\n    'search/suggest.json?' +\n    params.toString();\n\n  try {\n    const response = await fetch(url, {\n      signal: request.signal\n    });\n\n    if (!response.ok) {\n      throw new Error(`HTTP ${response.status}`);\n    }\n\n    const data = await response.json();\n\n    // 避免渲染已经过时的搜索结果\n    if (version !== requestVersion) return;\n\n    if (document.activeElement !== input) return;\n\n    if (query !== input.value.trim()) return;\n\n    const products =\n      data.resources.results.products;\n\n    // 将商品标题作为搜索建议，并去重\n    const titles = [\n      ...new Set(products.map(product => product.title))\n    ];\n\n    renderResults(\n      titles.map(title => ({ title }))\n    );\n\n  } catch (error) {\n    if (\n      error.name === 'AbortError' ||\n      version !== requestVersion\n    ) {\n      return;\n    }\n\n    hideResults();\n\n    status.textContent =\n      'Search suggestions are unavailable. ' +\n      'You can still submit your search.';\n\n  } finally {\n    if (version === requestVersion) {\n      list.setAttribute('aria-busy', 'false');\n    }\n  }\n}\n```\n\n这里的请求 URL 使用 `window.Shopify.routes.root`，以支持 Shopify 的 locale-aware URL。\n\n### 8.7 JavaScript：Debounce 与输入法处理\n\n```javascript\nfunction scheduleSearch() {\n  cancelPendingSearch();\n\n  hideResults();\n\n  results = [];\n  list.replaceChildren();\n\n  status.textContent = '';\n\n  const query = input.value.trim();\n\n  if (!query) return;\n\n  const version = requestVersion;\n\n  list.setAttribute('aria-busy', 'true');\n\n  debounceTimer = setTimeout(() => {\n    fetchSuggestions(query, version);\n  }, 250);\n}\n\ninput.addEventListener('input', event => {\n  if (event.isComposing) return;\n\n  scheduleSearch();\n});\n\ninput.addEventListener('compositionstart', () => {\n  dismissResults();\n});\n\ninput.addEventListener('compositionend', () => {\n  scheduleSearch();\n});\n```\n\n为什么需要处理输入法？\n\n例如中文、日文等输入法在文字正式输入之前，会经历 Composition（组合输入）过程。\n\n如果没有处理 `isComposing`，可能在用户尚未完成一个词语时就不断发起请求，甚至在用户按 Enter 确认输入法候选词时意外触发搜索提交。\n\n---\n\n## 9. 实现 Combobox 的完整键盘交互\n\n继续编写上面的 JavaScript。\n\n### 9.1 确认当前建议\n\n```javascript\nfunction selectOption(index) {\n  const option = results[index];\n\n  if (!option) return;\n\n  input.value = option.title;\n\n  dismissResults();\n\n  input.focus();\n\n  form.requestSubmit();\n}\n```\n\n这里使用 `requestSubmit()`，而不是直接调用 `form.submit()`。\n\n因为 `requestSubmit()` 更接近正常的表单提交行为，可以触发 submit 事件及适用的表单验证。\n\n### 9.2 键盘导航\n\n```javascript\ninput.addEventListener('keydown', event => {\n  if (event.isComposing || event.keyCode === 229) {\n    return;\n  }\n\n  switch (event.key) {\n    case 'ArrowDown': {\n      if (!results.length) return;\n\n      event.preventDefault();\n\n      openResults();\n\n      setActive(\n        (activeIndex + 1) % results.length\n      );\n\n      break;\n    }\n\n    case 'ArrowUp': {\n      if (!results.length) return;\n\n      event.preventDefault();\n\n      openResults();\n\n      setActive(\n        activeIndex <= 0\n          ? results.length - 1\n          : activeIndex - 1\n      );\n\n      break;\n    }\n\n    case 'Enter': {\n      if (!list.hidden && activeIndex >= 0) {\n        event.preventDefault();\n\n        selectOption(activeIndex);\n      }\n\n      // 没有活动项时，保留原生表单提交\n      break;\n    }\n\n    case 'Escape': {\n      if (!list.hidden ||\n          list.getAttribute('aria-busy') === 'true') {\n        event.preventDefault();\n        event.stopPropagation();\n\n        dismissResults();\n      }\n\n      break;\n    }\n\n    case 'Tab': {\n      dismissResults();\n\n      // 不调用 preventDefault()\n      break;\n    }\n  }\n});\n```\n\n这段代码中有三个非常值得关注的细节。\n\n第一，只有存在活动建议项时，才拦截 Enter。否则用户可以直接搜索自己输入的关键词。\n\n第二，Esc 优先关闭当前建议列表。如果建议列表已经关闭，则允许 Esc 继续传递给外层 Search Modal。\n\n第三，Tab 只负责离开组件，不应该被 Focus Trap 限制在搜索框内部。\n\n### 9.3 鼠标和触屏交互\n\n```javascript\nlist.addEventListener('mousedown', event => {\n  if (event.target.closest('[role=\"option\"]')) {\n    // 避免鼠标按下时 input 提前失去焦点\n    event.preventDefault();\n  }\n});\n\nlist.addEventListener('click', event => {\n  const option = event.target.closest('[role=\"option\"]');\n\n  if (!option) return;\n\n  selectOption(\n    Number(option.dataset.index)\n  );\n});\n\nform.addEventListener('focusout', event => {\n  if (\n    event.relatedTarget &&\n    event.relatedTarget !== input\n  ) {\n    dismissResults();\n  }\n});\n\ndocument.addEventListener('click', event => {\n  if (!form.contains(event.target)) {\n    dismissResults();\n  }\n});\n\ninput.addEventListener('focus', () => {\n  if (input.value.trim()) {\n    scheduleSearch();\n  }\n});\n```\n\n这里特别需要注意一个事件顺序问题：\n\n");
