out.push("\n\n### 8.8 渲染建议列表\n\n```javascript\nfunction renderResults(products) {\n  // 清理对旧 DOM 节点的引用\n  setActiveOption(-1);\n\n  const fragment = document.createDocumentFragment();\n\n  products.forEach((product, index) => {\n    const option = document.createElement('li');\n\n    option.id = `SearchOption-${index}`;\n\n    option.setAttribute('role', 'option');\n\n    option.setAttribute('aria-selected', 'false');\n\n    option.dataset.index = String(index);\n\n    option.textContent = product.title;\n\n    fragment.appendChild(option);\n  });\n\n  listbox.replaceChildren(fragment);\n\n  if (products.length) {\n    openResults();\n\n    status.textContent =\n      `${products.length} product suggestions found.`;\n  } else {\n    hideResults();\n\n    status.textContent = 'No product suggestions found.';\n  }\n}\n```\n\n这里故意使用 `textContent` 而不是通过字符串拼接 `innerHTML`，避免将商品标题错误地解释为 HTML。\n\n同时，在替换选项之前清理 aria-activedescendant，避免它指向已经被删除的旧节点。\n\n本示例的 result ID 只适用于单个搜索组件；多个搜索实例应加入唯一前缀。\n\n### 8.9 输入防抖与中文输入法处理\n\n```javascript\nfunction scheduleSearch() {\n  cancelPendingSearch();\n  hideResults();\n\n  results = [];\n  status.textContent = '';\n\n  const query = input.value.trim();\n\n  if (!query) {\n    listbox.replaceChildren();\n    return;\n  }\n\n  debounceTimer = setTimeout(() => {\n    fetchSuggestions(query);\n  }, 250);\n}\n\ninput.addEventListener('input', event => {\n  if (event.isComposing || composing) return;\n\n  scheduleSearch();\n});\n\ninput.addEventListener('compositionstart', () => {\n  composing = true;\n\n  closeResults();\n});\n\ninput.addEventListener('compositionend', () => {\n  composing = false;\n\n  scheduleSearch();\n});\n```\n\n为什么需要处理 compositionstart 和 compositionend？\n\n例如用户使用中文输入法输入“衬衫”，中间可能经历：\n\n```text\nc\nch\nchen\nchenshan\n衬衫\n```\n\n不应该把所有尚未确认的拼音都发送到 Predictive Search API，也不应该在用户通过 Enter 确认中文候选字时，错误地跳转到商品详情页。\n\n这不仅是性能问题，也是国际化和键盘无障碍问题。\n\n### 8.10 完整键盘交互\n\n```javascript\nfunction commitOption(index) {\n  const product = results[index];\n\n  if (!product) return;\n\n  closeResults();\n\n  window.location.assign(product.url);\n}\n\ninput.addEventListener('keydown', event => {\n  if (\n    composing ||\n    event.isComposing ||\n    event.keyCode === 229\n  ) {\n    return;\n  }\n\n  switch (event.key) {\n    case 'ArrowDown':\n      if (results.length) {\n        event.preventDefault();\n\n        openResults();\n\n        setActiveOption(\n          (activeIndex + 1) % results.length\n        );\n      }\n      break;\n\n    case 'ArrowUp':\n      if (results.length) {\n        event.preventDefault();\n\n        openResults();\n\n        setActiveOption(\n          activeIndex <= 0\n            ? results.length - 1\n            : activeIndex - 1\n        );\n      }\n      break;\n\n    case 'Enter':\n      if (!listbox.hidden && activeIndex >= 0) {\n        event.preventDefault();\n\n        commitOption(activeIndex);\n      }\n\n      // 没有活动项时，保留原生表单提交\n      break;\n\n    case 'Escape':\n      if (\n        !listbox.hidden ||\n        listbox.getAttribute('aria-busy') === 'true'\n      ) {\n        event.preventDefault();\n        event.stopPropagation();\n\n        closeResults();\n      } else {\n        cancelPendingSearch();\n      }\n      break;\n\n    case 'Tab':\n      closeResults();\n\n      // 不阻止 Tab 的原生行为\n      break;\n  }\n});\n```\n\n这里没有拦截 ArrowLeft、ArrowRight、Home、End 等文本编辑按键。\n\n另外，Predictive Search 如果位于 Search Modal 内部，Esc 应当优先关闭当前搜索建议列表，而不是立即关闭整个 Search Modal。\n\n父级 Modal 的 Esc 处理器也应该尊重已经处理过的事件。\n\n### 8.11 鼠标、触屏与外部关闭\n\n```javascript\nlistbox.addEventListener('mousedown', event => {\n  if (event.target.closest('[role=\"option\"]')) {\n    // 避免鼠标按下时输入框提前失去焦点\n    event.preventDefault();\n  }\n});\n\nlistbox.addEventListener('click', event => {\n  const option = event.target.closest('[role=\"option\"]');\n\n  if (!option) return;\n\n  commitOption(Number(option.dataset.index));\n});\n\ndocument.addEventListener('pointerdown', event => {\n  if (!form.contains(event.target)) {\n    closeResults();\n  }\n});\n\ndocument.addEventListener('focusin', event => {\n  if (event.target !== input) {\n    closeResults();\n  }\n});\n\ninput.addEventListener('focus', () => {\n  if (input.value.trim() && !composing) {\n    scheduleSearch();\n  }\n});\n```\n\n至此，我们已经将前面学习的六项核心能力整合到了一个组件中：\n\n| 知识 | 实际应用 |\n|---|---|\n| HTML 语义 | form、label、input |\n| ARIA | combobox、listbox、option |\n| Focus Management | DOM 焦点保留在 input |\n| Keyboard | 方向键、Enter、Esc |\n| AccName | 搜索框及列表名称 |\n| Live Region | 搜索结果数量通知 |\n\n该代码采用的是**商品建议确认后直接导航到商品页**的电商搜索模式，而非仅将选项文字填入 input 的通用 Combobox。它覆盖主要交互流程，但仍属于教学版本：尚未加入多实例管理、组件卸载、完整本地化、结果缓存、图片价格渲染及全部触屏辅助技术兼容性处理。\n\n---\n\n## 9. Select-only Combobox：自定义 Select 应该怎么实现？\n\n上一节的 Predictive Search 允许用户自由输入。\n\n但如果我们开发的是商品尺寸选择器、国家选择器或者自定义排序下拉框，用户只能从已有选项中选择，就可以采用 Select-only Combobox。\n\n### 9.1 HTML 结构\n\n```html\n<span id=\"sort-label\">Sort by</span>\n\n<div\n  id=\"sort-combobox\"\n  role=\"combobox\"\n  tabindex=\"0\"\n  aria-labelledby=\"sort-label\"\n  aria-expanded=\"false\"\n  aria-controls=\"sort-options\"\n>\n  Best selling\n</div>\n\n<ul\n  id=\"sort-options\"\n  role=\"listbox\"\n  aria-labelledby=\"sort-label\"\n  hidden\n>\n  <li\n    id=\"sort-option-1\"\n    role=\"option\"\n    aria-selected=\"true\"\n    data-value=\"best-selling\"\n  >\n    Best selling\n  </li>\n\n  <li\n    id=\"sort-option-2\"\n    role=\"option\"\n    aria-selected=\"false\"\n    data-value=\"price-ascending\"\n  >\n    Price, low to high\n  </li>\n\n  <li\n    id=\"sort-option-3\"\n    role=\"option\"\n    aria-selected=\"false\"\n    data-value=\"price-descending\"\n  >\n    Price, high to low\n  </li>\n</ul>\n\n<input\n  type=\"hidden\"\n  name=\"sort_by\"\n  value=\"best-selling\"\n>\n```\n\n它与 Editable Combobox 最大的区别在于：\n\n- 不提供自由文字输入。\n- 方向键和字符键可以用于选项导航。\n- 不需要 `aria-autocomplete`。\n- 需要自行维护用于表单提交的实际值。\n\n### 9.2 焦点与已确认值\n\n");
